mkuse!{use rustc_hir :: intravisit :: nested_filter :: NestedFilter ;}
mkuse!{use crate :: ty :: TyCtxt ;}
mkitem!{mkstruct!{# [doc = " Do not visit nested item-like things, but visit nested things"] # [doc = " that are inside of an item-like."] # [doc = ""] # [doc = " Notably, possible occurrences of bodies in non-item-like things"] # [doc = " include: closures/coroutines, inline `const {}` blocks, and"] # [doc = " constant arguments of types, e.g. in `let _: [(); /* HERE */];`."] # [doc = ""] # [doc = " **This is the most common choice.** A very common pattern is"] # [doc = " to use `visit_all_item_likes_in_crate()` as an outer loop,"] # [doc = " and to have the visitor that visits the contents of each item"] # [doc = " using this setting."] pub struct OnlyBodies (()) ;}}
mkitem!{mkimpl!{impl < 'tcx > NestedFilter < 'tcx > for OnlyBodies { type MaybeTyCtxt = TyCtxt < 'tcx > ; const INTER : bool = false ; const INTRA : bool = true ; }}}
mkitem!{mkstruct!{# [doc = " Visits all nested things, including item-likes."] # [doc = ""] # [doc = " **This is an unusual choice.** It is used when you want to"] # [doc = " process everything within their lexical context. Typically you"] # [doc = " kick off the visit by doing `walk_krate()`."] pub struct All (()) ;}}
mkitem!{mkimpl!{impl < 'tcx > NestedFilter < 'tcx > for All { type MaybeTyCtxt = TyCtxt < 'tcx > ; const INTER : bool = true ; const INTRA : bool = true ; }}}